/* @autogenerated */
import { Inject, Injectable, signal } from '@angular/core';
import { IDENTITY_PROVIDER, IdentityHandler, IdentityProvider } from './identity-provider.interface';
import { RuntimeConfigService } from '../config/app-config.service';
import { IdentityConfig } from '../config/app-config.model';
import { Logger } from '../observability/logger.service';
import { distinctUntilChanged, Observable, ReplaySubject, switchMap, take, throwError } from 'rxjs';

/** No hay ningún handler para ese nombre: el `type` de la configuración es inválido o ambiguo. */
export class IdentityNotConfiguredError extends Error {
  constructor(public readonly identity: string) {
    super(`No identity handler configured for "${identity}"`);
    this.name = 'IdentityNotConfiguredError';
  }
}

/** Tiempo máximo que se muestra el aviso de redirección si el navegador no llega a salir de la página. */
const REDIRECT_TIMEOUT_MS = 30_000;

@Injectable({ providedIn: 'root' })
export class IdentityService {
  private readonly handlers = new Map<string, IdentityHandler>();
  /** Emite cuando los handlers ya se han resuelto a partir de la configuración. */
  private readonly configured = new ReplaySubject<void>(1);
  /** Redirección al proveedor de identidad en curso: la UI muestra un aviso hasta que el navegador cambia de página. */
  readonly redirecting = signal<'login' | 'logout' | null>(null);

  public constructor(
    config: RuntimeConfigService,
    @Inject(IDENTITY_PROVIDER) identityProviders: IdentityProvider[],
    private readonly logger: Logger,
  ) {
    // En un microfront la configuración llega tarde: se espera a que cargue y se reconfigura solo si cambia
    config
      .value$('identity')
      .pipe(distinctUntilChanged((a, b) => JSON.stringify(a) === JSON.stringify(b)))
      .subscribe((conf) => {
        this.configure(conf ?? {}, identityProviders);
        this.configured.next();
      });
  }

  bootstrap(name: string): Observable<void> {
    return this.fromHandler(name, (handler) => handler.bootstrap());
  }

  /** Access token de `name`; falla con `IdentityNotConfiguredError` si no hay handler. */
  token(name: string): Observable<string | null> {
    return this.fromHandler(name, (handler) => handler.token$());
  }

  login(name: string): void {
    const handler = this.handlers.get(name);
    if (handler) {
      this.markRedirect('login');
      handler.login();
    }
  }

  logout(name: string): void {
    const handler = this.handlers.get(name);
    if (handler) {
      this.markRedirect('logout');
      handler.logout();
    }
  }

  private markRedirect(kind: 'login' | 'logout') {
    this.redirecting.set(kind);
    // Al volver con "atrás" el navegador puede restaurar la página desde bfcache con el aviso aún visible
    window.addEventListener('pageshow', (e) => e.persisted && this.redirecting.set(null), { once: true });
    // Si la redirección no llega a producirse (discovery caído, error del handler…) no se deja la UI bloqueada
    setTimeout(() => this.redirecting.set(null), REDIRECT_TIMEOUT_MS);
  }

  private fromHandler<T>(name: string, fn: (handler: IdentityHandler) => Observable<T>): Observable<T> {
    return this.configured.pipe(
      take(1),
      switchMap(() => {
        const handler = this.handlers.get(name);
        return handler ? fn(handler) : throwError(() => new IdentityNotConfiguredError(name));
      }),
    );
  }

  private configure(conf: Record<string, IdentityConfig>, providers: IdentityProvider[]) {
    this.handlers.clear();
    Object.entries(conf).forEach(([key, value]) => {
      const valids = providers.map((p) => p.accept(value?.type ?? '', key)).filter((h) => h != null);
      if (valids.length === 1) {
        this.handlers.set(key, valids[0]);
      } else if (valids.length) {
        this.logger.error(`More than one identity handler for type "${value?.type}" of "${key}"`);
      } else {
        this.logger.error(`No identity handler for type "${value?.type}" of "${key}"`);
      }
    });
  }
}
